terale SX","assi":[{"codice":"colore","nome":"Colore","valori":[{"codice":"standard","nome":"Colore standard da definire"}]},{"codice":"tipologia_vetro","nome":"Tipologia vetro","valori":[{"codice":"standard","nome":"Vetro standard da definire"}]},{"codice":"telaio","nome":"Telaio","valori":[{"codice":"telaio_a_l","nome":"Telaio a L"},{"codice":"telaio_a_z","nome":"Telaio a Z"}]}]},{"id":"finestra_2_ante_fisso_dx","nome":"Finestra 2 ante con fisso laterale DX","assi":[{"codice":"colore","nome":"Colore","valori":[{"codice":"standard","nome":"Colore standard da definire"}]},{"codice":"tipologia_vetro","nome":"Tipologia vetro","valori":[{"codice":"standard","nome":"Vetro standard da definire"}]},{"codice":"telaio","nome":"Telaio","valori":[{"codice":"telaio_a_l","nome":"Telaio a L"},{"codice":"telaio_a_z","nome":"Telaio a Z"}]}]},{"id":"finestra_fisso_centrale","nome":"Finestra con fisso centrale e 2 ante laterali","assi":[{"codice":"colore","nome":"Colore","valori":[{"codice":"standard","nome":"Colore standard da definire"}]},{"codice":"tipologia_vetro","nome":"Tipologia vetro","valori":[{"codice":"standard","nome":"Vetro standard da definire"}]},{"codice":"telaio","nome":"Telaio","valori":[{"codice":"telaio_a_l","nome":"Telaio a L"},{"codice":"telaio_a_z","nome":"Telaio a Z"}]}]},{"id":"porta_finestra_2_ante_fisso_sx","nome":"Porta finestra 2 ante con fisso laterale SX","assi":[{"codice":"soglia","nome":"Soglia","valori":[{"codice":"con","nome":"Con soglia"},{"codice":"senza","nome":"Senza soglia"}]},{"codice":"colore","nome":"Colore","valori":[{"codice":"standard","nome":"Colore standard da definire"}]},{"codice":"tipologia_vetro","nome":"Tipologia vetro","valori":[{"codice":"standard","nome":"Vetro standard da definire"}]},{"codice":"telaio","nome":"Telaio","valori":[{"codice":"telaio_a_l","nome":"Telaio a L"},{"codice":"telaio_a_z","nome":"Telaio a Z"}]}]},{"id":"porta_finestra_2_ante_fisso_dx","nome":"Porta finestra 2 ante con fisso laterale DX","assi":[{"codice"